def mod(s):
    return re.sub(r'([Мм]одул(?:ь|я|е|ю|ем)|модулей)\s+(\d+)(?!\.\d|\d)',lambda m:m.group(1)+' «'+MOD[m.group(2)]+'»' if m.group(2) in MOD else m.group(0),s)
def urok(s):
    W={'':'татья','а':'татьи','е':'татье','у':'татье','ов':'татей','ах':'татьях','ам':'татьям'}
    def f(m):
        pre,suf,a,b=m.group(1),m.group(2),m.group(3),m.group(4)
        w=('С' if pre=='У' else 'с')+W[suf]
        names=ART[a]+((' и '+ART[b]) if b else '')
        return w+' '+names
    return re.sub(r'([Уу])рок(ов|ах|ам|а|е|у|)\s+(\d+\.\d+)(?:–(\d+\.\d+))?',f,s)
def mk(fid):
    d=json.load(open(D+fid+'.json',encoding='utf-8'));Sx={x['id']:x for x in d['sections']}
    items=list(Sx['faq']['blocks'][0]['items'])
    st=[b for b in Sx['zadanie']['blocks'] if b['type']=='task'][0]['stuck']
    for q,a in st:
        if STUCKDROP.get(fid) and STUCKDROP[fid] in q: continue
        q=re.sub(r'^Если ','',q)
        a=a[0].upper()+a[1:]; a=a if a.endswith('.') else a+'.'
        items.append(['Что делать, если '+q[0].lower()+q[1:]+'?',a])
    Sx['faq']['blocks'][0]['items']=items[:8]
    ai=dict([b for b in Sx['ai']['blocks'] if b['type']=='ai'][0]); ai['steps']=STEPS[fid]
    Sx['ai']['blocks']=[ai,{'type':'note','title':'Почему здесь нет готовых промптов','text':'Всё, что ты собираешь по ходу статьи: %s — данные для агента. Он напишет формулировки под твой конкретный проект. Чужой промпт подходит чужому проекту.'%NOTE[fid]}]
    Sx['primery']['title']='Пример'; Sx['primery']['nav']='Пример'
    for x in d['sections']:
        x['blocks']=[b for b in x['blocks'] if not(b['type']=='note' and b.get('title') in KILLNOTE) and b['type'] not in('prompt','builder')]
    d['sections']=[x for x in d['sections'] if x['id'] not in('prompty','check','zadanie')]
    g=[x for x in d['sections'] if x['id']=='glavnoe'][0]['blocks']
    t1,t2=GL[fid]; g[1]['text']=t1
    if t2: g[2]['text']=t2
    if fid in LEAD: d['lead']='<b>'+LEAD[fid]+'</b>'+d['lead'].split('</b>',1)[1]
    d['quiz']=QUIZ[fid]
    if fid=='l9_1':
        d['stage']['next']='Статья '+ART['9.2']+': шоты с ударом и контактом уходят в Kling, а этот же шот станет контрольным для сравнения.'
    if fid=='l9_2':
        d['lead']='<b>Kling лучше всего подходит для шотов с физикой (удар, падение, контакт) и для шотов с заданными первым и последним кадром.</b>'+d['lead'].split('</b>',1)[1]
        g=[x for x in d['sections'] if x['id']=='glavnoe'][0]['blocks']
        g[0]={'type':'chain','nodes':[{'b':'Первый кадр','small':'стартовая картинка'},{'b':'Действие цепочкой','small':'slowly… then… finally…','on':True},{'b':'Физика и камера','small':'масса, контакт, одна формулировка камеры'},{'b':'Последний кадр','small':'правка первого в Nano Banana'}]}
        g[1]['text']='Kling лучше других моделей держит массу и момент контакта: удар, падение, всплеск, спорт. Он умеет приходить в заданный последний кадр (first/last frame), поэтому подходит и для шотов, где герой перемещается из одной точки в другую.'
        g[2]['text']='Промпт Kling пишется цепочкой без таймкодов: одно главное действие на отрезок, физика словами и одна формулировка камеры. Какую модель брать под какой шот, разобрано в статье '+ART['9.3']+'.'
        d['sections']=[x for x in d['sections'] if x['id']!='vybor']
        d['stage']['next']='Модуль «Звук и монтаж»: отобранные шоты идут в монтаж.'
    if fid=='l9_3':
        raw=json.load(open(D+'l9_2.json',encoding='utf-8'))
